/**
 * Jinx Innkeeper + Riot: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Innkeeper
 * Wiki: https://wiki.bloodontheclocktower.com/Riot
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`. Replace the `it.todo` with tests of the rule
 * the jinx imposes, where the engine can check it (for example a setup warning when only one
 * of the two may be in play). Paraphrase, never copy wiki prose.
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong, type Script } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import type { Command } from '#lib/core/engine/index.ts';
import { castWith } from '#lib/core/model/fixtures.test-support.ts';
import { gameEnds } from '#lib/core/rules/game-end.ts';
import { ownJinxRules } from '#lib/core/rules/jinxes.ts';

const scriptOf = (ids: string[]): Script => ({
	meta: { name: 'Jinxed' },
	entries: ids.map((id) => ({ kind: 'official' as const, id }))
});

describe('Innkeeper + Riot jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'innkeeper', 'riot');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('innkeeper')?.name).toBe('Innkeeper');
		expect(data.byId.get('riot')?.name).toBe('Riot');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['innkeeper', 'riot'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['innkeeper'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['riot'])).not.toContain(jinx);
	});

	// Both pages' Related Jinxes: if Riot nominates a player the Innkeeper protects and they are
	// executed, good wins. Read from the day's log and the Innkeeper's Safe token. A drunk or
	// poisoned Innkeeper may not have protected them, so that is a hold, the Storyteller's call.
	describe('good wins when Riot executes a player the Innkeeper protects', () => {
		const ids = ['riot', 'innkeeper', 'chef', 'empath', 'poisoner', 'washerwoman', 'butler'];
		const cast = castWith({ script: scriptOf(ids) });
		const mark =
			(i: number) =>
			(s: string[]): Command => ({
				type: 'AddReminder',
				seatId: s[i],
				reminder: { characterId: 'innkeeper', label: 'Safe' }
			});
		const nominate =
			(by: number, who: number) =>
			(s: string[]): Command => ({
				type: 'Nominate',
				nominator: s[by],
				nominee: s[who]
			});
		const execute =
			(i: number) =>
			(s: string[]): Command => ({ type: 'Execute', seatId: s[i] });
		const newDay: Command = { type: 'NewDay' };

		it("is data in the Riot's rules", () => {
			expect(ownJinxRules({ script: scriptOf(ids) }, 'riot', 'innkeeper')).toEqual({
				endsGame: { kind: 'nominated-marked-executed', winner: 'good', token: 'Safe' }
			});
		});

		it('ends the game for good', () => {
			const { game, ctx, seats } = cast(ids, mark(2), newDay, nominate(0, 2), execute(2));
			expect(
				gameEnds(game, ctx.characters).map((e) => [e.rule, e.winner, e.jinxedWith, e.seats])
			).toEqual([['nominated-marked-executed', 'good', 'innkeeper', [seats[2], seats[0]]]]);
		});

		it('does not when someone else nominated them, or they were not protected', () => {
			const other = cast(ids, mark(2), newDay, nominate(3, 2), execute(2));
			expect(gameEnds(other.game, other.ctx.characters)).toEqual([]);
			const unmarked = cast(ids, newDay, nominate(0, 5), execute(5));
			expect(gameEnds(unmarked.game, unmarked.ctx.characters)).toEqual([]);
		});

		it('is held while the Innkeeper is poisoned', () => {
			const poisoned = (s: string[]): Command => ({
				type: 'AddReminder',
				seatId: s[1],
				reminder: { characterId: 'poisoner', label: 'Poisoned' }
			});
			const { game, ctx, seats } = cast(ids, poisoned, mark(2), newDay, nominate(0, 2), execute(2));
			expect(gameEnds(game, ctx.characters).map((e) => e.holds)).toEqual([
				[
					{
						rule: 'impaired',
						characterId: 'innkeeper',
						seats: [seats[1]],
						wiki: expect.any(String)
					}
				]
			]);
		});
	});
});
